SourceCode.Declaration:
/// <summary>
/// search request: what was typed or scanned on the app's Home search, and the worker's warehouse.
/// </summary>
[DataContractAttribute]
class HSMobileOpsSearchRequest
{
    DataAreaId dataAreaId;
    str        warehouseId;
    str        query;
}

Method.Source:
[DataMemberAttribute('DataAreaId')]
public DataAreaId parmDataAreaId(DataAreaId _value = dataAreaId)
{
    dataAreaId = _value;
    return dataAreaId;
}

[DataMemberAttribute('WarehouseId')]
public str parmWarehouseId(str _value = warehouseId)
{
    warehouseId = _value;
    return warehouseId;
}

[DataMemberAttribute('Query')]
public str parmQuery(str _value = query)
{
    query = _value;
    return query;
}
